#include "audio_features_vectors.h"

void audio_features_vector_samples(int16_t *samples) {
    uint32_t state = 1;

    for (int n = 0; n < AUDIO_FEATURES_PATCH_SAMPLES; n++) {
        int32_t saw = (n % 200 - 100) * 80;
        if (n >= 4000 && n < 4800) {
            saw *= 5;
        }

        int32_t tone = 0;
        if (n >= 7800) {
            tone = n % 3 == 0 ? 2000 : -1000;
        }

        state = (state * 1103515245u + 12345u) & 0x7FFFFFFFu;
        int32_t noise = (int32_t)((state >> 16) & 0xFFFu) - 2048;

        int32_t value = saw + tone + noise;
        if (value > INT16_MAX) {
            value = INT16_MAX;
        }
        if (value < INT16_MIN) {
            value = INT16_MIN;
        }
        samples[n] = (int16_t)value;
    }
}

